"""Markdown views of the catalogue (generated; do not edit by hand)."""
from __future__ import annotations

from collections import defaultdict

SEM = {1: "S1", 2: "S2", 3: "ST1", 4: "ST2"}


def _sems(c) -> str:
    return ", ".join(SEM.get(s, str(s)) for s in c["offered"]) or "not offered"


def write_courses_md(path, cat):
    cs = cat["courses"]
    lines = [
        f"# Course catalogue, AY{cat['acad_year']}",
        "",
        "Generated by `python -m m1_data build`; edit the parser or `data/manual/overrides.json`, not this file.",
        f"Data fetched from NUSMods on {cat['fetched_at']}. Student context: "
        f"programme {', '.join(cat['student_context'].get('programs', []))}, "
        f"cohort {cat['student_context'].get('cohort')}.",
        "",
        "How to read a block: **Prereq** uses `and` / `or` / `n of (...)`; a course counts at grade D or",
        "better unless marked `[>=X]`. **Blocked if** = the student cannot take the course once they",
        "have completed what it lists. **Mutually exclusive** adds courses that list this one.",
        "Search for `### CS3263` to jump to a course. Machine-readable version: `catalog.json`.",
        "",
        "## Index",
        "",
    ]
    by_prefix = defaultdict(list)
    for code, c in cs.items():
        if c["exists_in_ay"]:
            by_prefix[code.rstrip("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ")[:4] or code[:2]].append(code)
    for p in sorted(by_prefix, key=lambda p: (p != "CS", p)):
        lines.append(f"- **{p}**: " + ", ".join(by_prefix[p]))
    lines += ["", "## Courses", ""]

    for p in sorted(by_prefix, key=lambda p: (p != "CS", p)):
        for code in by_prefix[p]:
            c = cs[code]
            flag = "" if c["available"] else " (not available to this student)"
            lines.append(f"### {code}: {c['title']}{flag}")
            lines.append("")
            lines.append(f"- {c['mc']} MC · {_sems(c)} · scope: {c['scope']}")
            lines.append(f"- **Prereq:** {c['prereq']['text']}")
            if c["coreq"]["logic"] is not None:
                lines.append(f"- **Coreq:** {c['coreq']['text']}")
            lines.append(f"- **Blocked if:** {c['preclusion']['text']}")
            extra = sorted(set(c["preclusion"]["mutually_exclusive_with"]) - set(c["preclusion"]["courses"]))
            if extra:
                lines.append(f"- **Also mutually exclusive with:** {', '.join(extra)}")
            if c["unlocks"]:
                lines.append(f"- **Unlocks:** {', '.join(c['unlocks'])}")
            for why in c["unavailable_reasons"]:
                lines.append(f"- **Unavailable:** {why}")
            for a in c["assumptions"]:
                lines.append(f"- _Assumed:_ {a}")
            for wmsg in c["warnings"]:
                lines.append(f"- ⚠ {wmsg}")
            for o in c["overrides"]:
                lines.append(f"- ✎ manual override: {o}")
            lines.append("")

    stubs = [c for c in cs.values() if not c["exists_in_ay"]]
    lines += ["## Referenced but not in this AY", "",
              "Old or renamed codes that other courses still mention (e.g. in preclusions). "
              "They can appear in a transcript but cannot be planned.", ""]
    for c in stubs:
        mx = c["preclusion"]["mutually_exclusive_with"]
        lines.append(f"- {c['code']}" + (f" (mutually exclusive with {', '.join(mx)})" if mx else ""))
    path.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")


SPOT_CHECK_CORE = ["CS3263", "CS2109S", "CS2109HS", "CS3244", "CS4248",          # from the doc
                   "CS1231S", "CS2030S", "CS2040S", "CS2100", "CS2103T", "CS2106",
                   "CS3230", "CS3243", "CS2309", "CS4262", "CS4240", "CS3242"]


def write_spot_check_md(path, cat, n_random: int = 8, seed: int = 3263):
    """One-off checklist for hand-verifying against nusmods.com. Never overwritten."""
    import random
    if path.exists():
        return False
    cs = cat["courses"]
    full = [c for c, v in cs.items() if v["details"] == "full"]
    warned = [c for c in full if cs[c]["warnings"]]
    pool = sorted(set(full) - set(SPOT_CHECK_CORE) - set(warned))
    rnd = random.Random(seed).sample(pool, min(n_random, len(pool)))
    picks = [c for c in SPOT_CHECK_CORE if c in cs] + warned + sorted(rnd)
    L = ["# Spot-check sheet", "",
         "The doc requires our parsed prerequisites and exclusions to be checked by hand against",
         "NUSMods **before** any instances are generated (target: 29 Oct). For each row open the link,",
         "compare, then put your initials in **Checked** and ✅ or ❌ in **OK**. For ❌, add a fix to",
         "`data/manual/overrides.json` (or fix the parser) and note it here.", "",
         f"Rows: the doc's 5 courses + BComp CS core, every course with a parser warning, "
         f"and {len(rnd)} random courses (seed {seed}).", "",
         "| Course | Prereq (ours) | Blocked if (ours) | Available | Checked | OK | Notes |",
         "|---|---|---|---|---|---|---|"]
    for c in picks:
        v = cs[c]
        L.append(f"| [{c}](https://nusmods.com/courses/{c}) | {v['prereq']['text']} | "
                 f"{v['preclusion']['text']} | {'yes' if v['available'] else 'no'} |  |  |  |")
    path.write_text("\n".join(L) + "\n", encoding="utf-8", newline="\n")
    return True


def write_report_md(path, cat, crosscheck, parse_errors):
    s = cat["stats"]
    cs = cat["courses"]
    L = [f"# Parse report, AY{cat['acad_year']}", "",
         f"Generated {cat['generated_at']} from data fetched {cat['fetched_at']}.", "",
         "## Summary", "", "| Metric | Value |", "|---|---|"]
    L += [f"| {k} | {v} |" for k, v in s.items()]
    L += ["", "## Cross-check: prerequisiteRule vs NUSMods prereqTree", "",
          "Both sources are parsed and resolved independently; they should give the same logic.",
          f"Matches: {len(crosscheck['match'])}. Mismatches: {len(crosscheck['mismatch'])}. "
          f"Rule but no tree: {len(crosscheck['no_tree'])} "
          f"({', '.join(crosscheck['no_tree']) or 'none'}).", ""]
    if crosscheck["mismatch"]:
        L += ["| Course | From prerequisiteRule | From prereqTree | Resolution |", "|---|---|---|---|"]
        L += [f"| {m['code']} | {m['from_rule']} | {m['from_prereqTree']} | {m.get('resolution', '')} |"
              for m in crosscheck["mismatch"]]
        L.append("")
    L += ["## Parse errors", ""] + ([f"- {e}" for e in parse_errors] or ["None."]) + [""]
    L += ["## Not available to this student", ""]
    L += [f"- {c} ({cs[c]['title']}): {'; '.join(cs[c]['unavailable_reasons'])}"
          for c in cs if cs[c]["exists_in_ay"] and not cs[c]["available"]] or ["None."]
    L += ["", "## Warnings (spot-check these first)", ""]
    L += [f"- {c}: {'; '.join(cs[c]['warnings'])}" for c in cs if cs[c]["warnings"]] or ["None."]
    L += ["", "## Asymmetric preclusions", "",
          "A lists B as a preclusion but B (in this AY) does not list A. Treated as mutual anyway.", ""]
    asym = []
    for c, v in cs.items():
        for x in v["preclusion"]["courses"]:
            if x in cs and cs[x]["exists_in_ay"] and c not in cs[x]["preclusion"]["courses"]:
                asym.append(f"{c} → {x}")
    L += [", ".join(asym) if asym else "None."]
    path.write_text("\n".join(L) + "\n", encoding="utf-8", newline="\n")
